verifiche.codice:
extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	clear_printed()
	var scene := await instantiate_scene("res://star.tscn")
	if not check("star_loaded", scene != null, "La scena star.tscn deve aprirsi senza errori"):
		return
	var star := scene as Sprite2D
	if not check("star_type", star != null, "La radice della scena star.tscn deve essere uno Sprite2D"):
		return
	check("pos", star.position == Vector2(576, 80), "La stella deve trovarsi a Vector2(576, 80)")
	check("modulate", star.modulate == Color.YELLOW, "La stella deve essere colorata con Color.YELLOW")
	check("output", "Stella pronta:" in printed_text(), "Lo script deve stampare un testo contenente 'Stella pronta:'")
